# Import of required libraries
import skyramp
import os
import time
import json


from SkyrampUtils import (
    URL_localhost,
    create_category,
    create_recipe,
    delete_recipe,
    get_recipe_statistics,
)


def update_recipe_with_two_categories(
    client, headers, slug, category_response, category_1_response, expected_status=200
):
    # Request Body
    recipes_recipes_PATCH_request_body = r'''{
        "recipeCategory": [
            {
                "id": "21111111-2222-4333-8444-555555555551",
                "name": "SkyrampMultiCatOne",
                "slug": "skyrampmulticatone"
            },
            {
                "id": "22111111-2222-4333-8444-555555555552",
                "name": "SkyrampMultiCatTwo",
                "slug": "skyrampmulticattwo"
            }
        ]
    }'''

    # Execute Request
    recipes_recipes_PATCH_response = client.send_request(
        url=URL_localhost,
        path="/api/recipes/{recipes}",
        method="PATCH",
        body=recipes_recipes_PATCH_request_body,
        headers=headers,
        path_params={"recipes": slug},
        data_override={
            "recipeCategory.0.id": skyramp.get_response_value(category_response, "id"),
            "recipeCategory.0.name": skyramp.get_response_value(category_response, "name"),
            "recipeCategory.0.slug": skyramp.get_response_value(category_response, "slug"),
            "recipeCategory.1.id": skyramp.get_response_value(category_1_response, "id"),
            "recipeCategory.1.name": skyramp.get_response_value(category_1_response, "name"),
            "recipeCategory.1.slug": skyramp.get_response_value(category_1_response, "slug")
        }
    )

    # Generated Assertions
    assert recipes_recipes_PATCH_response.status_code == expected_status

    return recipes_recipes_PATCH_response


def test_integration():
    # Invocation of Skyramp Client
    client = skyramp.Client()
    # Definition of authentication header
    headers = {}
    if os.getenv("SKYRAMP_TEST_TOKEN") is not None:
        headers["Authorization"] = "Bearer " + os.getenv("SKYRAMP_TEST_TOKEN")

    statistics_GET_response = get_recipe_statistics(client, headers)

    baseline_total = skyramp.get_response_value(statistics_GET_response, "total")
    assert baseline_total is not None
    assert baseline_total >= 0

    categories_POST_response = create_category(client, headers, "SkyrampMultiCatOne")

    category_one_name = skyramp.get_response_value(categories_POST_response, "name")
    assert category_one_name.startswith("SkyrampMultiCatOne-")
    assert category_one_name not in json.loads(
        statistics_GET_response.response_body
    )["by_category"]

    categories_POST_1_response = create_category(client, headers, "SkyrampMultiCatTwo")

    category_two_name = skyramp.get_response_value(categories_POST_1_response, "name")
    assert category_two_name.startswith("SkyrampMultiCatTwo-")
    assert category_two_name != category_one_name

    recipes_POST_response = create_recipe(client, headers, "Skyramp Multi Cat Recipe")

    recipes = json.loads(recipes_POST_response.response_body)
    assert recipes.startswith("skyramp-multi-cat-recipe-")

    recipes_recipes_PATCH_response = update_recipe_with_two_categories(
        client, headers, recipes, categories_POST_response, categories_POST_1_response
    )

    assert skyramp.get_response_value(recipes_recipes_PATCH_response, "slug") == recipes
    assert skyramp.get_response_value(
        recipes_recipes_PATCH_response, "recipeCategory.0.name"
    ) == category_one_name
    assert skyramp.get_response_value(
        recipes_recipes_PATCH_response, "recipeCategory.1.name"
    ) == category_two_name

    statistics_GET_1_response = get_recipe_statistics(client, headers)

    statistics_GET_1_body = json.loads(statistics_GET_1_response.response_body)
    assert statistics_GET_1_body["total"] == baseline_total + 1
    assert statistics_GET_1_body["by_category"][category_one_name] == 1
    assert statistics_GET_1_body["by_category"][category_two_name] == 1

    recipes_recipes_DELETE_response = delete_recipe(
        client, headers, skyramp.get_response_value(recipes_recipes_PATCH_response, "slug")
    )


if __name__ == "__main__":
    test_integration()
